INSERT INTO `collections` VALUES (1,'New Season','new-season','Autumn / Winter','The first chapter of the season — outerwear, tailoring and the pieces that anchor a wardrobe.',NULL,'https://images.unsplash.com/photo-1526413232644-8a40f03cc03b?w=1400&q=80&auto=format&fit=crop&h=1750',NULL,1,0,0,NULL,NULL,NULL,NULL,0,'2026-09-15 23:21:09','2026-09-15 23:21:09','fashion',1),(2,'Essentials','essentials',NULL,'Elevated basics in organic cotton, linen and merino. The foundation of everything else.',NULL,'https://images.unsplash.com/photo-1558769132-cb1aea458c5e?w=1400&q=80&auto=format&fit=crop&h=1750',NULL,1,0,1,NULL,NULL,NULL,NULL,0,'2026-09-15 23:21:09','2026-09-15 23:21:09','fashion',1),(3,'Signature Collection','signature',NULL,'Our most recognisable silhouettes, reimagined each season with new fabrics and finishes.',NULL,'https://images.unsplash.com/photo-1610652492500-ded49ceeb378?w=1400&q=80&auto=format&fit=crop&h=1750',NULL,1,1,2,NULL,NULL,NULL,NULL,0,'2026-09-15 23:21:09','2026-09-15 23:21:09','fashion',1),(4,'Fragrance Edit','fragrance-edit',NULL,'Six compositions created with master perfumers in Grasse.',NULL,'https://images.unsplash.com/photo-1622618991746-fe6004db3a47?w=1400&q=80&auto=format&fit=crop&h=1750',NULL,1,0,3,NULL,NULL,NULL,NULL,0,'2026-09-15 23:21:09','2026-09-15 23:21:09','fashion',1),(5,'Timepieces','timepieces',NULL,'Swiss-made automatic and quartz watches built to be handed down.',NULL,'https://images.unsplash.com/photo-1619134778706-7015533a6150?w=1400&q=80&auto=format&fit=crop&h=1750',NULL,1,0,4,NULL,NULL,NULL,NULL,0,'2026-09-15 23:21:09','2026-09-15 23:21:09','fashion',1),(6,'Leather Collection','leather',NULL,'Bags, belts and small leather goods, cut from vegetable-tanned hides.',NULL,'https://images.unsplash.com/photo-1521223890158-f9f7c3d5d504?w=1400&q=80&auto=format&fit=crop&h=1750',NULL,1,0,5,NULL,NULL,NULL,NULL,0,'2026-09-15 23:21:09','2026-09-15 23:21:09','fashion',1),(7,'Weekend Edit','weekend-edit',NULL,'Softer tailoring, washed fabrics and pieces made for slower days.',NULL,'https://images.unsplash.com/photo-1596755094514-f87e34085b2c?w=1400&q=80&auto=format&fit=crop&h=1750',NULL,1,0,6,NULL,NULL,NULL,NULL,0,'2026-09-15 23:21:09','2026-09-15 23:21:09','fashion',1),(8,'Evening Edit','evening-edit',NULL,'Sharp lines, deep tones and a little shine for after dark.',NULL,'https://images.unsplash.com/photo-1550639525-c97d455acf70?w=1400&q=80&auto=format&fit=crop&h=1750',NULL,1,0,7,NULL,NULL,NULL,NULL,0,'2026-09-15 23:21:09','2026-09-15 23:21:09','fashion',1),(9,'Gift Collection','gift-collection',NULL,'Curated gifts for every occasion, wrapped by hand in our signature ivory box.',NULL,'https://images.unsplash.com/photo-1617038220319-276d3cfab638?w=1400&q=80&auto=format&fit=crop&h=1750',NULL,1,0,8,NULL,NULL,NULL,NULL,0,'2026-09-15 23:21:10','2026-09-15 23:21:10','fashion',1),(10,'Breakfast Essentials','breakfast-essentials',NULL,'Milk, bread, eggs, butter and everything for a quick morning.',NULL,'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=1200&q=80&auto=format&fit=crop&h=1500',NULL,1,1,100,NULL,NULL,NULL,NULL,0,'2026-09-17 23:44:55','2026-09-17 23:44:55','grocery',2),(11,'Monthly Grocery List','monthly-grocery-list',NULL,'The big-pack staples every Indian kitchen restocks each month.',NULL,'https://images.unsplash.com/photo-1586201375761-83865001e31c?w=1200&q=80&auto=format&fit=crop&h=1500',NULL,1,0,101,NULL,NULL,NULL,NULL,0,'2026-09-17 23:44:55','2026-09-17 23:44:55','grocery',2),(12,'Movie Night','movie-night',NULL,'Chips, chocolates, colas and pizza for the couch.',NULL,'https://images.unsplash.com/photo-1566478989037-eec170784d0b?w=1200&q=80&auto=format&fit=crop&h=1500',NULL,1,0,102,NULL,NULL,NULL,NULL,0,'2026-09-17 23:44:55','2026-09-17 23:44:55','grocery',2),(13,'Healthy Picks','healthy-picks',NULL,'Fresh fruit, greens, nuts and green tea for a lighter week.',NULL,'https://images.unsplash.com/photo-1615485290382-441e4d049cb5?w=1200&q=80&auto=format&fit=crop&h=1500',NULL,1,0,103,NULL,NULL,NULL,NULL,0,'2026-09-17 23:44:55','2026-09-17 23:44:55','grocery',2),(14,'Everyday Essentials','everyday-essentials',NULL,'Rice, dal, atta, oil and spices — the pantry you restock every month.',NULL,'https://images.unsplash.com/photo-1586201375761-83865001e31c?w=1200&q=80&auto=format&fit=crop&h=900',NULL,1,0,200,NULL,NULL,NULL,NULL,0,'2026-09-18 01:19:44','2026-09-18 01:19:44','heritage',3),(15,'Healthy Breakfast','healthy-breakfast',NULL,'Poha, millets, honey, seeds and teas for a lighter start.',NULL,'https://images.unsplash.com/photo-1547592180-85f173990554?w=1200&q=80&auto=format&fit=crop&h=900',NULL,1,0,201,NULL,NULL,NULL,NULL,0,'2026-09-18 01:19:44','2026-09-18 01:19:44','heritage',3),(16,'Festive Cooking','festive-cooking',NULL,'Ghee, cardamom, dry fruits and basmati for the celebrations.',NULL,'https://images.unsplash.com/photo-1585937421612-70a008356fbe?w=1200&q=80&auto=format&fit=crop&h=900',NULL,1,1,202,NULL,NULL,NULL,NULL,0,'2026-09-18 01:19:44','2026-09-18 01:19:44','heritage',3),(17,'Kitchen Essentials','kitchen-essentials',NULL,'The spice box, the oils and the flours every Indian kitchen runs on.',NULL,'https://images.unsplash.com/photo-1532336414038-cf19250c5757?w=1200&q=80&auto=format&fit=crop&h=900',NULL,1,0,203,NULL,NULL,NULL,NULL,0,'2026-09-18 01:19:44','2026-09-18 01:19:44','heritage',3),(18,'Premium Staples','premium-staples',NULL,'Single-origin, small-batch versions of the classics.',NULL,'https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=1200&q=80&auto=format&fit=crop&h=900',NULL,1,0,204,NULL,NULL,NULL,NULL,0,'2026-09-18 01:19:44','2026-09-18 01:19:44','heritage',3),(19,'Wellness Foods','wellness-foods',NULL,'Ayurvedic staples and superfoods, tested for purity.',NULL,'https://images.unsplash.com/photo-1615485500704-8e990f9900f7?w=1200&q=80&auto=format&fit=crop&h=900',NULL,1,0,205,NULL,NULL,NULL,NULL,0,'2026-09-18 01:19:44','2026-09-18 01:19:44','heritage',3),(20,'Bathroom starter kit','bathroom-starter-kit',NULL,'Everything a new bathroom needs: mixer, shower, health faucet, angle cocks and hoses.',NULL,NULL,NULL,1,0,200,NULL,NULL,NULL,NULL,0,'2026-09-21 03:03:58','2026-09-21 03:03:58','plumbing',4),(21,'CPVC hot-water line kit','cpvc-hot-water-line',NULL,'Pipe, elbows, tees, brass adapters and cement for a complete hot & cold line.',NULL,NULL,NULL,1,0,201,NULL,NULL,NULL,NULL,0,'2026-09-21 03:03:58','2026-09-21 03:03:58','plumbing',4),(22,'Overhead tank setup','overhead-tank-setup',NULL,'Tank, float valve, ball valves, pump and check valve for a rooftop water system.',NULL,NULL,NULL,1,0,202,NULL,NULL,NULL,NULL,0,'2026-09-21 03:03:58','2026-09-21 03:03:58','plumbing',4),(23,'Plumber’s toolkit','plumbers-toolkit',NULL,'The tools and consumables every plumber carries.',NULL,NULL,NULL,1,0,203,NULL,NULL,NULL,NULL,0,'2026-09-21 03:03:58','2026-09-21 03:03:58','plumbing',4);
