INSERT INTO `faqs` VALUES (1,'Orders','How do I place an order?','Add pieces to your bag, proceed to checkout and follow the steps for contact details, delivery address and payment. You will receive a confirmation email with your order number immediately.',0,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(2,'Orders','Can I change or cancel my order?','Orders can be changed or cancelled within two hours of being placed. Contact client care with your order number and we will do our best to help before the order is dispatched.',1,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(3,'Orders','Where is my order confirmation?','Confirmations are sent within minutes to the email used at checkout. Please check your spam folder; if it is still missing, contact client care.',2,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(4,'Shipping','How long does delivery take?','Standard delivery takes 3–5 business days across India. Express delivery arrives in 1–2 business days in metro cities. International delivery takes 5–10 business days.',3,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(5,'Shipping','Do you offer free shipping?','Yes — standard delivery is complimentary on orders over ₹15,000 and express delivery is complimentary over ₹40,000.',4,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(6,'Shipping','Do you ship internationally?','We ship to over 40 countries. Duties and taxes are calculated at checkout so there are no surprises on delivery.',5,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(7,'Returns','What is your return policy?','You have 30 days from delivery to return any unworn piece with its tags attached for a full refund. Returns are collected from your door at no charge.',6,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(8,'Returns','How do I start a return?','Sign in to your account, open the order and choose “Start a return”, or contact client care with your order number. We will arrange collection within 48 hours.',7,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(9,'Exchanges','Can I exchange for a different size?','Yes. Request an exchange within 30 days and we will send the new size as soon as the original is collected — usually within 2–3 business days.',8,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(10,'Exchanges','Can I exchange a gift?','Gifts can be exchanged for another size or colour, or for store credit, within 30 days of the original delivery date.',9,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(11,'Payments','Which payment methods do you accept?','Visa, Mastercard, American Express, RuPay, UPI, net banking, major wallets and cash on delivery (a small handling fee applies to COD).',10,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(12,'Payments','Is my payment information secure?','All payments are processed over 256-bit encrypted connections by PCI-DSS compliant partners. We never store your card details.',11,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(13,'Products','How do I find my size?','Every product page links to our size guide with detailed measurements. If you are between sizes, we suggest sizing up for outerwear and down for knitwear.',12,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(14,'Products','Are your products authentic?','Every piece is designed by the house and made in our partner ateliers. Each order ships with a certificate of authenticity.',13,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(15,'Account','Do I need an account to order?','No — you can check out as a guest. An account lets you track orders, save addresses and keep a wishlist across devices.',14,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(16,'Account','How do I reset my password?','Use “Forgot password” on the sign-in page and we will email you a secure reset link.',15,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(17,'General','Do you have physical boutiques?','Yes. Our flagship is in Bengaluru with boutiques in Mumbai and New Delhi. See the store locator for hours and directions.',16,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(18,'General','How can I contact you?','Email care@maisonelan.com or call +91 80 4500 1200, Monday to Saturday, 10:00–19:00 IST.',17,1,'2026-09-16 00:23:01','2026-09-16 00:23:01','fashion',1),(19,'Orders','How fast will my order arrive?','<p>Most orders arrive within 10–30 minutes of being placed. You can watch the live status on your order page.</p>',0,1,'2026-09-18 01:01:49','2026-09-18 01:01:49','grocery',2),(20,'Orders','Is there a minimum order value?','<p>No minimum. Small orders may carry a delivery charge, which is shown at checkout before you pay.</p>',1,1,'2026-09-18 01:01:49','2026-09-18 01:01:49','grocery',2),(21,'Orders','Can I change or cancel an order?','<p>Yes — until it is packed. Open the order from your account and tap Cancel. After packing, use the fresh guarantee for any issue.</p>',2,1,'2026-09-18 01:01:49','2026-09-18 01:01:49','grocery',2),(22,'Shipping','Which areas do you deliver to?','<p>Bengaluru, Mumbai, Delhi NCR, Hyderabad, Chennai, Pune, Kolkata and Ahmedabad. Enter your pincode in the header to check your locality.</p>',3,1,'2026-09-18 01:01:49','2026-09-18 01:01:49','grocery',2),(23,'Shipping','What are your delivery hours?','<p>7 am to 11 pm, all days including holidays.</p>',4,1,'2026-09-18 01:01:49','2026-09-18 01:01:49','grocery',2),(24,'Shipping','Can I schedule a delivery?','<p>Yes. Choose a delivery option at checkout and we will deliver in that window.</p>',5,1,'2026-09-18 01:01:49','2026-09-18 01:01:49','grocery',2),(25,'Returns','What if an item is not fresh?','<p>Report it from your order page within 24 hours and we will replace or refund it — no questions asked.</p>',6,1,'2026-09-18 01:01:49','2026-09-18 01:01:49','grocery',2),(26,'Returns','How long do refunds take?','<p>3–5 business days to the original payment method. Cash-on-delivery refunds go to your wallet or bank account.</p>',7,1,'2026-09-18 01:01:49','2026-09-18 01:01:49','grocery',2),(27,'Payments','Which payment methods do you accept?','<p>UPI, credit and debit cards, wallets, net banking and cash on delivery.</p>',8,1,'2026-09-18 01:01:49','2026-09-18 01:01:49','grocery',2),(28,'Payments','Are prices inclusive of GST?','<p>Yes. The bill you see at checkout is what you pay — no surprises at the door.</p>',9,1,'2026-09-18 01:01:49','2026-09-18 01:01:49','grocery',2),(29,'Products','What do the green and red marks mean?','<p>A green mark means the product is vegetarian; a red mark means it contains egg, meat or fish.</p>',10,1,'2026-09-18 01:01:49','2026-09-18 01:01:49','grocery',2),(30,'Products','How do you keep produce fresh?','<p>Fruits and vegetables arrive from farms and mandis every morning and are stored chilled at the dark store until they are packed for you.</p>',11,1,'2026-09-18 01:01:49','2026-09-18 01:01:49','grocery',2),(31,'Account','Do I need an account to order?','<p>No, you can check out as a guest. An account lets you save addresses, reorder in one tap and track every order.</p>',12,1,'2026-09-18 01:01:49','2026-09-18 01:01:49','grocery',2),(32,'General','Do you offer a subscription for milk or bread?','<p>Not yet — one-tap reorders from your account are the quickest way to restock daily essentials.</p>',13,1,'2026-09-18 01:01:49','2026-09-18 01:01:49','grocery',2),(46,'Orders','How long does delivery take?','<p>2–3 business days to metro cities and 3–5 days elsewhere. Orders placed before 2 pm ship the same day.</p>',0,1,'2026-09-18 02:23:07','2026-09-18 02:23:07','heritage',3),(47,'Orders','Is there free delivery?','<p>Yes — on all orders above ₹999. Smaller orders carry a flat charge shown at checkout.</p>',1,1,'2026-09-18 02:23:07','2026-09-18 02:23:07','heritage',3),(48,'Orders','Can I order in bulk or for corporate gifting?','<p>Yes. Write to us through the contact page with quantities and we will send a quote within one business day.</p>',2,1,'2026-09-18 02:23:07','2026-09-18 02:23:07','heritage',3),(49,'Products','Are your products certified organic?','<p>Products in the Organic Foods section are India Organic / NPOP certified. Other products are natural and minimally processed but may come from farms still in conversion.</p>',3,1,'2026-09-18 02:23:07','2026-09-18 02:23:07','heritage',3),(50,'Products','Why does my honey or ghee look different from the last jar?','<p>Natural products vary by season. Raw honey crystallises and ghee turns granular in cooler weather — both are signs of purity, not spoilage.</p>',4,1,'2026-09-18 02:23:07','2026-09-18 02:23:07','heritage',3),(51,'Products','What do the dietary tags mean?','<p>Tags such as Organic, Vegan, Gluten-free and Stone-ground describe how a product was grown or made. Use the dietary filter on any listing to shop by them.</p>',5,1,'2026-09-18 02:23:07','2026-09-18 02:23:07','heritage',3),(52,'Products','How do I know the harvest date?','<p>Every pack prints its harvest or milling date, origin and lot number. Flours are milled weekly; dry fruits are nitrogen-flushed for freshness.</p>',6,1,'2026-09-18 02:23:07','2026-09-18 02:23:07','heritage',3),(53,'Shipping','Do you deliver outside India?','<p>Not yet. We currently deliver to 19,000+ pincodes within India.</p>',7,1,'2026-09-18 02:23:07','2026-09-18 02:23:07','heritage',3),(54,'Returns','What if my order arrives damaged?','<p>Send us a photo within 7 days and we will replace or refund it in full.</p>',8,1,'2026-09-18 02:23:07','2026-09-18 02:23:07','heritage',3),(55,'Returns','Can I return an opened product?','<p>For hygiene reasons opened food cannot be returned unless it is defective. Unopened gift boxes can be returned within 7 days.</p>',9,1,'2026-09-18 02:23:07','2026-09-18 02:23:07','heritage',3),(56,'Payments','Which payment methods do you accept?','<p>UPI, credit and debit cards, net banking, wallets and cash on delivery.</p>',10,1,'2026-09-18 02:23:07','2026-09-18 02:23:07','heritage',3),(57,'Account','Do I need an account?','<p>You can check out as a guest. An account saves addresses, tracks orders and lets you reorder your pantry in one tap.</p>',11,1,'2026-09-18 02:23:07','2026-09-18 02:23:07','heritage',3),(58,'General','Where do your products come from?','<p>From farmer collectives in twelve Indian states — Punjab and Haryana for wheat and basmati, Kerala for spices and red rice, Karnataka for millets, Meghalaya for turmeric, the Nilgiris for honey.</p>',12,1,'2026-09-18 02:23:07','2026-09-18 02:23:07','heritage',3),(73,'Orders','Do you sell to individuals or only to contractors?','<p>Both. Homeowners get the same genuine products; contractors and builders get volume pricing through the bulk quote form.</p>',0,1,'2026-09-21 03:22:13','2026-09-21 03:22:13','plumbing',4),(74,'Orders','Can I get a GST invoice?','<p>Yes. Add your GSTIN in the order notes or on your account and the invoice is issued in your business name for input credit.</p>',1,1,'2026-09-21 03:22:13','2026-09-21 03:22:13','plumbing',4),(75,'Orders','Is there a minimum order value?','<p>No minimum. Orders below the free-delivery threshold carry a small delivery charge shown at checkout.</p>',2,1,'2026-09-21 03:22:13','2026-09-21 03:22:13','plumbing',4),(76,'Shipping','How long does delivery take?','<p>Dispatch within 24 hours on working days. Fittings, taps and tools arrive in 2–4 days; pipes, tanks, pumps and sanitaryware in 4–6 days by surface transport.</p>',3,1,'2026-09-21 03:22:13','2026-09-21 03:22:13','plumbing',4),(77,'Shipping','Do you deliver 3 m and 6 m pipes?','<p>Yes. Long pipes ship in bundles on dedicated transport. A freight charge based on your pincode is shown before payment.</p>',4,1,'2026-09-21 03:22:13','2026-09-21 03:22:13','plumbing',4),(78,'Shipping','Can you deliver to a construction site?','<p>Yes — mention the site address and an on-site contact in the order notes and we will schedule the delivery.</p>',5,1,'2026-09-21 03:22:13','2026-09-21 03:22:13','plumbing',4),(79,'Products','Are the products genuine?','<p>Every product comes from the brand or its authorised distributor and carries the manufacturer warranty.</p>',6,1,'2026-09-21 03:22:13','2026-09-21 03:22:13','plumbing',4),(80,'Products','How do I choose between PVC, CPVC and UPVC?','<p>CPVC for hot & cold water lines, UPVC for cold water supply, PVC for drainage, agriculture and low-pressure lines. Every product page lists the applications.</p>',7,1,'2026-09-21 03:22:13','2026-09-21 03:22:13','plumbing',4),(81,'Products','Which pipe size do I need?','<p>Half-inch for individual taps, three-quarter inch for bathroom branch lines, one inch and above for mains and tank connections. Our support team can size a full plan for you.</p>',8,1,'2026-09-21 03:22:13','2026-09-21 03:22:13','plumbing',4),(82,'Payments','Which payment methods do you accept?','<p>UPI, credit and debit cards, net banking, wallets and cash on delivery.</p>',9,1,'2026-09-21 03:22:13','2026-09-21 03:22:13','plumbing',4),(83,'Payments','Are prices inclusive of GST?','<p>Yes. The price you see is the price you pay, and the GST breakup is printed on your invoice.</p>',10,1,'2026-09-21 03:22:13','2026-09-21 03:22:13','plumbing',4),(84,'Returns','What can be returned?','<p>Unused products in original packing within 7 days. Cut pipes, opened cement and installed sanitaryware cannot be returned.</p>',11,1,'2026-09-21 03:22:13','2026-09-21 03:22:13','plumbing',4),(85,'Returns','What if an item arrives damaged?','<p>Report it from your order page within 48 hours with photos and we replace it free of cost.</p>',12,1,'2026-09-21 03:22:13','2026-09-21 03:22:13','plumbing',4),(86,'Bulk orders','How do bulk quotes work?','<p>Send your requirement through the Bulk Quote form or WhatsApp. A project executive replies with pricing and delivery schedule within one working day.</p>',13,1,'2026-09-21 03:22:13','2026-09-21 03:22:13','plumbing',4),(87,'Services','How quickly can a plumber arrive?','For emergencies, usually within 60–90 minutes in our main service areas. For scheduled work you choose the day and a morning, afternoon or evening slot, and we confirm the time on call.',0,1,'2026-09-21 04:18:59','2026-09-21 04:18:59','plumbing-services',5),(88,'Services','Do you provide emergency plumbing?','Yes — 24×7, including Sundays and holidays, for burst pipes, major leaks, overflowing drains and no-water situations. Call the emergency number or use “Get emergency help”.',1,1,'2026-09-21 04:18:59','2026-09-21 04:18:59','plumbing-services',5),(89,'Services','Which areas do you service?','Ludhiana, Chandigarh, Mohali, Panchkula, Zirakpur, Jalandhar, Amritsar and Patiala, with the localities listed on each service-area page. Not sure? Call us and we will check.',2,1,'2026-09-21 04:18:59','2026-09-21 04:18:59','plumbing-services',5),(90,'Booking','Do you provide estimates before starting work?','Always. The plumber inspects the problem, tells you the cost of labour and parts, and starts only after you approve. For bigger jobs we send a written estimate first.',3,1,'2026-09-21 04:18:59','2026-09-21 04:18:59','plumbing-services',5),(91,'Booking','Can I book a plumber online?','Yes. Use “Book a plumber”, pick the service, describe the problem, choose a date and slot, and share your contact details. You get a reference number and a confirmation call.',4,1,'2026-09-21 04:18:59','2026-09-21 04:18:59','plumbing-services',5),(92,'Booking','How do I know the plumber is genuine?','Every plumber is background-verified and trained by us. You receive the plumber’s name before the visit and they carry a PipeCare ID card.',5,1,'2026-09-21 04:19:00','2026-09-21 04:19:00','plumbing-services',5),(93,'Services','Do you handle commercial plumbing?','Yes — shops, restaurants, offices, hospitals, hotels and housing societies, including annual maintenance contracts and after-hours visits.',6,1,'2026-09-21 04:19:00','2026-09-21 04:19:00','plumbing-services',5),(94,'Services','Do you provide maintenance services?','Yes. Our plumbing maintenance service covers a full inspection of lines, taps, valves, tanks and pumps with minor repairs done on the spot and a written report.',7,1,'2026-09-21 04:19:00','2026-09-21 04:19:00','plumbing-services',5),(95,'Booking','Is there a warranty on the work?','Every job carries a 30-day work warranty. If the same problem returns within 30 days, we fix it free of charge.',8,1,'2026-09-21 04:19:00','2026-09-21 04:19:00','plumbing-services',5),(96,'Booking','What payment methods do you accept?','UPI, cards and cash after the work is done. A GST invoice is provided on every job.',9,1,'2026-09-21 04:19:00','2026-09-21 04:19:00','plumbing-services',5);
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

