INSERT INTO `order_items` VALUES (20,15,80,'Stone-ground Whole Wheat Atta','HG-3011','https://images.unsplash.com/photo-1574323347407-f5e1ad6d020b?w=900&q=80&auto=format&fit=crop&h=900','5 kg',NULL,NULL,NULL,329,1,329,'2026-09-18 02:21:29','2026-09-18 02:21:29'),(33,21,75,'Unpolished Toor Dal','HG-3006','https://images.unsplash.com/photo-1515543904379-3d757afe72e4?w=900&q=80&auto=format&fit=crop&h=900','1 kg',NULL,NULL,NULL,189,1,189,'2026-09-21 02:38:14','2026-09-21 02:38:14'),(34,22,98,'Raw Forest Honey','HG-3029','https://images.unsplash.com/photo-1555211652-5c6222f971bc?w=900&q=80&auto=format&fit=crop&h=900','500 g',NULL,NULL,NULL,449,1,449,'2026-09-21 02:38:38','2026-09-21 02:38:38'),(35,24,70,'Aged Basmati Rice','HG-3001','https://images.unsplash.com/photo-1586201375761-83865001e31c?w=900&q=80&auto=format&fit=crop&h=900','1 kg',NULL,NULL,NULL,499,1,499,'2026-09-21 02:43:43','2026-09-21 02:43:43'),(42,27,129,'Hindware Contessa Plus Wall Mixer with Bend','PK-3018','https://images.unsplash.com/photo-1567102109796-90071d28cb38?w=900&q=80&auto=format&fit=crop&h=900','Standard',NULL,NULL,NULL,3690,1,3690,'2026-09-21 04:06:21','2026-09-21 04:06:21');
