INSERT INTO `projects` VALUES (1,'plumbing-services','Bathroom tap replacement','bathroom-tap-replacement-model-town',9,'https://images.unsplash.com/photo-1680008702835-d79e376a5f79?w=1000&q=80&auto=format&fit=crop&h=750','https://images.unsplash.com/photo-1610278764397-388d11c35ddb?w=1000&q=80&auto=format&fit=crop&h=750','A corroded 12-year-old tap that leaked at the base, replaced with a new quarter-turn tap, fresh angle valve and connector. Done in 40 minutes.','Model Town, Ludhiana','2026-09-14',1,0,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(2,'plumbing-services','Toilet flush & base repair','toilet-repair-sector-70',10,'https://images.unsplash.com/photo-1563204719-44395a035bb6?w=1000&q=80&auto=format&fit=crop&h=750','https://images.unsplash.com/photo-1587527901949-ab0341697c1e?w=1000&q=80&auto=format&fit=crop&h=750','Continuously running flush and a leak at the WC base. Replaced the fill valve and flush valve, re-seated the WC with a new wax ring.','Sector 70, Mohali','2026-09-03',1,1,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(3,'plumbing-services','Blocked drain line repair','drain-repair-manimajra',6,'https://images.unsplash.com/photo-1668961915523-884872e392f8?w=1000&q=80&auto=format&fit=crop&h=750','https://images.unsplash.com/photo-1741997376539-a63ee600dac9?w=1000&q=80&auto=format&fit=crop&h=750','Outdoor drain line collapsed and kept backing up. Replaced the damaged section with the correct gradient and a new inspection chamber.','Manimajra, Chandigarh','2026-08-23',1,2,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(4,'plumbing-services','GI to CPVC pipe replacement','pipe-replacement-urban-estate',4,'https://images.unsplash.com/photo-1606340671662-27ee685dd111?w=1000&q=80&auto=format&fit=crop&h=750','https://images.unsplash.com/photo-1694827893591-af9b80361599?w=1000&q=80&auto=format&fit=crop&h=750','Rusted GI supply lines causing brown water and weak flow. Replaced the full ground-floor run with CPVC in two days.','Urban Estate, Jalandhar','2026-08-12',1,3,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(5,'plumbing-services','Overhead tank installation','tank-installation-tripuri',11,'https://images.unsplash.com/photo-1646488993053-8c182b628696?w=1000&q=80&auto=format&fit=crop&h=750','https://images.unsplash.com/photo-1497990136619-d0c2de2b5b4b?w=1000&q=80&auto=format&fit=crop&h=750','Old cracked tank replaced with a new 1000 L three-layer tank on a raised stand, with new inlet, outlet, overflow and float valve.','Tripuri, Patiala','2026-08-01',1,4,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(6,'plumbing-services','Kitchen sink & RO plumbing','kitchen-plumbing-ranjit-avenue',8,'https://images.unsplash.com/photo-1618840626133-54463084a141?w=1000&q=80&auto=format&fit=crop&h=750','https://images.unsplash.com/photo-1645343804676-c5edd2272f9d?w=1000&q=80&auto=format&fit=crop&h=750','Leaking bottle trap and no proper RO connection. Fitted a new sink drain assembly, bottle trap and a dedicated RO inlet with a shut-off valve.','Ranjit Avenue, Amritsar','2026-07-21',1,5,'2026-09-21 04:18:59','2026-09-21 04:18:59',5);
