INSERT INTO `service_areas` VALUES (1,'plumbing-services','Ludhiana','ludhiana','Punjab','https://images.unsplash.com/photo-1632201147654-f6f54427e538?w=1200&q=80&auto=format&fit=crop&h=800','Same-day and emergency plumbers across Ludhiana — leak repair, pipes, drains, bathroom and kitchen plumbing, tanks and pumps.','<p>Our Ludhiana team covers Model Town, Sarabha Nagar, BRS Nagar, Civil Lines, Dugri, Pakhowal Road, Ferozepur Road, Haibowal, Jamalpur and Focal Point. Book online, call or WhatsApp and a verified plumber reaches you in about 60–90 min for emergencies, or at the slot you choose for scheduled work.</p><p>All jobs come with transparent pricing approved before work starts, genuine parts and our 30-day work warranty.</p>','[\"Model Town\",\"Sarabha Nagar\",\"BRS Nagar\",\"Civil Lines\",\"Dugri\",\"Pakhowal Road\",\"Ferozepur Road\",\"Haibowal\",\"Jamalpur\",\"Focal Point\"]','60–90 min',1,0,NULL,NULL,NULL,NULL,0,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(2,'plumbing-services','Chandigarh','chandigarh','Chandigarh','https://images.unsplash.com/photo-1630061712710-2539eb457c55?w=1200&q=80&auto=format&fit=crop&h=800','Same-day and emergency plumbers across Chandigarh — leak repair, pipes, drains, bathroom and kitchen plumbing, tanks and pumps.','<p>Our Chandigarh team covers Sector 15, Sector 22, Sector 35, Sector 44, Manimajra, Industrial Area, Sector 8 and Sector 49. Book online, call or WhatsApp and a verified plumber reaches you in about 60–90 min for emergencies, or at the slot you choose for scheduled work.</p><p>All jobs come with transparent pricing approved before work starts, genuine parts and our 30-day work warranty.</p>','[\"Sector 15\",\"Sector 22\",\"Sector 35\",\"Sector 44\",\"Manimajra\",\"Industrial Area\",\"Sector 8\",\"Sector 49\"]','60–90 min',1,1,NULL,NULL,NULL,NULL,0,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(3,'plumbing-services','Mohali','mohali','Punjab','https://images.unsplash.com/photo-1689574666551-52eb11c37bcd?w=1200&q=80&auto=format&fit=crop&h=800','Same-day and emergency plumbers across Mohali — leak repair, pipes, drains, bathroom and kitchen plumbing, tanks and pumps.','<p>Our Mohali team covers Phase 3B2, Phase 7, Sector 70, Sector 79, Kharar, Airport Road and Sunny Enclave. Book online, call or WhatsApp and a verified plumber reaches you in about 60–90 min for emergencies, or at the slot you choose for scheduled work.</p><p>All jobs come with transparent pricing approved before work starts, genuine parts and our 30-day work warranty.</p>','[\"Phase 3B2\",\"Phase 7\",\"Sector 70\",\"Sector 79\",\"Kharar\",\"Airport Road\",\"Sunny Enclave\"]','60–90 min',1,2,NULL,NULL,NULL,NULL,0,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(4,'plumbing-services','Jalandhar','jalandhar','Punjab','https://images.unsplash.com/photo-1632398535774-b95738ddff68?w=1200&q=80&auto=format&fit=crop&h=800','Same-day and emergency plumbers across Jalandhar — leak repair, pipes, drains, bathroom and kitchen plumbing, tanks and pumps.','<p>Our Jalandhar team covers Model Town, Urban Estate, Rama Mandi, Nakodar Road, Cantt and GT Road. Book online, call or WhatsApp and a verified plumber reaches you in about 90–120 min for emergencies, or at the slot you choose for scheduled work.</p><p>All jobs come with transparent pricing approved before work starts, genuine parts and our 30-day work warranty.</p>','[\"Model Town\",\"Urban Estate\",\"Rama Mandi\",\"Nakodar Road\",\"Cantt\",\"GT Road\"]','90–120 min',1,3,NULL,NULL,NULL,NULL,0,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(5,'plumbing-services','Amritsar','amritsar','Punjab','https://images.unsplash.com/photo-1577199001468-44c049e7603f?w=1200&q=80&auto=format&fit=crop&h=800','Same-day and emergency plumbers across Amritsar — leak repair, pipes, drains, bathroom and kitchen plumbing, tanks and pumps.','<p>Our Amritsar team covers Ranjit Avenue, Green Avenue, Majitha Road, Lawrence Road and Batala Road. Book online, call or WhatsApp and a verified plumber reaches you in about 90–120 min for emergencies, or at the slot you choose for scheduled work.</p><p>All jobs come with transparent pricing approved before work starts, genuine parts and our 30-day work warranty.</p>','[\"Ranjit Avenue\",\"Green Avenue\",\"Majitha Road\",\"Lawrence Road\",\"Batala Road\"]','90–120 min',1,4,NULL,NULL,NULL,NULL,0,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(6,'plumbing-services','Patiala','patiala','Punjab','https://images.unsplash.com/photo-1630309904321-4f320230bced?w=1200&q=80&auto=format&fit=crop&h=800','Same-day and emergency plumbers across Patiala — leak repair, pipes, drains, bathroom and kitchen plumbing, tanks and pumps.','<p>Our Patiala team covers Urban Estate, Leela Bhawan, Tripuri, Sirhind Road and Rajpura Road. Book online, call or WhatsApp and a verified plumber reaches you in about 90–120 min for emergencies, or at the slot you choose for scheduled work.</p><p>All jobs come with transparent pricing approved before work starts, genuine parts and our 30-day work warranty.</p>','[\"Urban Estate\",\"Leela Bhawan\",\"Tripuri\",\"Sirhind Road\",\"Rajpura Road\"]','90–120 min',1,5,NULL,NULL,NULL,NULL,0,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(7,'plumbing-services','Panchkula','panchkula','Haryana','https://images.unsplash.com/photo-1632398461363-741a64493ab6?w=1200&q=80&auto=format&fit=crop&h=800','Same-day and emergency plumbers across Panchkula — leak repair, pipes, drains, bathroom and kitchen plumbing, tanks and pumps.','<p>Our Panchkula team covers Sector 4, Sector 12, Sector 20, MDC and Pinjore. Book online, call or WhatsApp and a verified plumber reaches you in about 60–90 min for emergencies, or at the slot you choose for scheduled work.</p><p>All jobs come with transparent pricing approved before work starts, genuine parts and our 30-day work warranty.</p>','[\"Sector 4\",\"Sector 12\",\"Sector 20\",\"MDC\",\"Pinjore\"]','60–90 min',1,6,NULL,NULL,NULL,NULL,0,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(8,'plumbing-services','Zirakpur','zirakpur','Punjab','https://images.unsplash.com/photo-1646009445351-b8192e095f3a?w=1200&q=80&auto=format&fit=crop&h=800','Same-day and emergency plumbers across Zirakpur — leak repair, pipes, drains, bathroom and kitchen plumbing, tanks and pumps.','<p>Our Zirakpur team covers VIP Road, Patiala Road, Dhakoli, Peer Muchalla and Baltana. Book online, call or WhatsApp and a verified plumber reaches you in about 60–90 min for emergencies, or at the slot you choose for scheduled work.</p><p>All jobs come with transparent pricing approved before work starts, genuine parts and our 30-day work warranty.</p>','[\"VIP Road\",\"Patiala Road\",\"Dhakoli\",\"Peer Muchalla\",\"Baltana\"]','60–90 min',1,7,NULL,NULL,NULL,NULL,0,'2026-09-21 04:18:59','2026-09-21 04:18:59',5);
