INSERT INTO `testimonials` VALUES (1,'plumbing-services','Harpreet Kaur','Water was seeping into the flat below and two plumbers could not find it. PipeCare found the concealed leak in an hour and opened only two tiles. Very professional.',5,2,'Ludhiana',NULL,1,0,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(2,'plumbing-services','Rajesh Verma','Pipe burst at 11 pm. The plumber was at my door in 50 minutes, stopped the flooding and came back next morning for the proper repair. Lifesaver.',5,1,'Chandigarh',NULL,1,1,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(3,'plumbing-services','Simran Gill','Got both bathrooms redone. The estimate was clear, the work was clean and they coordinated with my tile guy. Zero leaks after six months.',5,7,'Mohali',NULL,1,2,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(4,'plumbing-services','Amit Bansal','Kitchen drain was blocked every month. They cleaned it with a machine and explained what to avoid. Has not blocked since.',4,5,'Ludhiana',NULL,1,3,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(5,'plumbing-services','Neha Sharma','Booked online for a dripping mixer. Plumber came on time, replaced the cartridge and even cleaned the aerators of the other taps.',5,9,'Panchkula',NULL,1,4,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(6,'plumbing-services','Gurpreet Singh','Tank cleaning done properly — drained, scrubbed, disinfected. They also replaced the float valve that was causing the overflow.',5,11,'Jalandhar',NULL,1,5,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(7,'plumbing-services','Pooja Mehta','Flush was running all night. Fixed in 30 minutes with a genuine part and the charge was exactly what they quoted on the phone.',5,10,'Zirakpur',NULL,1,6,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(8,'plumbing-services','Vikram Chaudhary','Pump was not lifting water. They found the foot valve was gone, replaced it and installed an auto-controller. No more running to the terrace.',4,12,'Patiala',NULL,1,7,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(9,'plumbing-services','Manpreet Dhillon','We use PipeCare for our restaurant. They come after closing hours and the kitchen drain problems are gone. Reliable team.',5,17,'Amritsar',NULL,1,8,'2026-09-21 04:18:59','2026-09-21 04:18:59',5),(10,'plumbing-services','Sunita Rani','New geyser installed with proper safety valve and CPVC line. Neat work and they took away the old unit.',5,13,'Chandigarh',NULL,1,9,'2026-09-21 04:18:59','2026-09-21 04:18:59',5);
/*!40000 ALTER TABLE `testimonials` ENABLE KEYS */;
